import Foundation
struct Motion {
static func animPhase(_ kind: String, _ p: Double, _ dir: Double, _ s: inout (alpha: Double, scale: Double, dy: Double)) {
    if kind == "none" || kind.isEmpty || p >= 1 { return }
    let q = max(0, p)
    let k = 1 - (1 - q) * (1 - q) * (1 - q)
    s.alpha *= k
    if kind == "slide" { s.dy += dir * (1 - k) * 0.06 }
    if kind == "slideDown" { s.dy -= dir * (1 - k) * 0.06 }
    if kind == "pop" {
      let b = 1 + 2.70158 * (q - 1) * (q - 1) * (q - 1) + 1.70158 * (q - 1) * (q - 1)
      s.scale *= 0.4 + 0.6 * b
    }
    if kind == "bounce" {
      var progress = q
      let bounce: Double
      if progress < 1 / 2.75 {
        bounce = 7.5625 * progress * progress
      } else if progress < 2 / 2.75 {
        progress -= 1.5 / 2.75
        bounce = 7.5625 * progress * progress + 0.75
      } else if progress < 2.5 / 2.75 {
        progress -= 2.25 / 2.75
        bounce = 7.5625 * progress * progress + 0.9375
      } else {
        progress -= 2.625 / 2.75
        bounce = 7.5625 * progress * progress + 0.984375
      }
      s.scale *= 0.55 + 0.45 * bounce
      s.dy += dir * (1 - bounce) * 0.045
    }
    if kind == "zoomIn" { s.scale *= 0.6 + 0.4 * k }
    if kind == "zoomOut" { s.scale *= 1.5 - 0.5 * k }
    if kind == "rise" {
      s.dy += dir * (1 - q) * 0.1
      s.scale *= 0.94 + 0.06 * k
    }
    if kind == "pulse" { s.scale *= 1 + 0.18 * (1 - q) * sin(q * .pi * 3) }
  }
}
let kinds: [String] = ["none","fade","slide","slideDown","pop","bounce","zoomIn","zoomOut","rise","pulse"]
let samples: [Double] = [-0.2,0,0.05,0.1,0.25,0.36363636363636365,0.5454545454545454,0.75,0.9,1,1.2]
for kind in kinds {
  for progress in samples {
    for direction in [1.0, -1.0] {
      var state = (alpha: 1.0, scale: 1.0, dy: 0.0)
      Motion.animPhase(kind, progress, direction, &state)
      print("\(kind)|\(progress)|\(direction)|\(state.alpha)|\(state.scale)|\(state.dy)")
    }
  }
}

