import kotlin.math.max
import kotlin.math.sin
private class AnimState(var alpha: Double = 1.0, var scale: Double = 1.0, var dy: Double = 0.0)
private class ExportText(val start: Double, val end: Double, val animIn: String, val animOut: String, val animDuration: Double)
private fun textAnimAt(t: ExportText, time: Double): AnimState {
  val s = AnimState()
  fun phase(kind: String, p: Double, dir: Double) {
    if (kind == "none" || kind.isEmpty() || p >= 1) return
    val q = max(0.0, p)
    val k = 1 - (1 - q) * (1 - q) * (1 - q)
    s.alpha *= k
    if (kind == "slide") s.dy += dir * (1 - k) * 0.06
    if (kind == "slideDown") s.dy -= dir * (1 - k) * 0.06
    if (kind == "pop") {
      val b = 1 + 2.70158 * (q - 1) * (q - 1) * (q - 1) + 1.70158 * (q - 1) * (q - 1)
      s.scale *= 0.4 + 0.6 * b
    }
    if (kind == "bounce") {
      var progress = q
      val bounce: Double
      if (progress < 1 / 2.75) {
        bounce = 7.5625 * progress * progress
      } else if (progress < 2 / 2.75) {
        progress -= 1.5 / 2.75
        bounce = 7.5625 * progress * progress + 0.75
      } else if (progress < 2.5 / 2.75) {
        progress -= 2.25 / 2.75
        bounce = 7.5625 * progress * progress + 0.9375
      } else {
        progress -= 2.625 / 2.75
        bounce = 7.5625 * progress * progress + 0.984375
      }
      s.scale *= 0.55 + 0.45 * bounce
      s.dy += dir * (1 - bounce) * 0.045
    }
    if (kind == "zoomIn") s.scale *= 0.6 + 0.4 * k
    if (kind == "zoomOut") s.scale *= 1.5 - 0.5 * k
    if (kind == "rise") {
      s.dy += dir * (1 - q) * 0.1
      s.scale *= 0.94 + 0.06 * k
    }
    if (kind == "pulse") s.scale *= 1 + 0.18 * (1 - q) * sin(q * Math.PI * 3)
  }
  if (t.animDuration <= 0) return s
  phase(t.animIn, (time - t.start) / t.animDuration, 1.0)
  phase(t.animOut, (t.end - time) / t.animDuration, -1.0)
  return s
}
fun main() {
  val kinds = listOf("none", "fade", "slide", "slideDown", "pop", "bounce", "zoomIn", "zoomOut", "rise", "pulse")
  val samples = listOf(-0.2, 0.0, 0.05, 0.1, 0.25, 1 / 2.75, 1.5 / 2.75, 0.75, 0.9, 1.0, 1.2)
  for (kind in kinds) {
    for (progress in samples) {
      for (direction in listOf(1.0, -1.0)) {
        val overlay = ExportText(0.0, 4.0, if (direction > 0) kind else "none", if (direction < 0) kind else "none", 0.5)
        val state = textAnimAt(overlay, if (direction > 0) progress * 0.5 else 4 - progress * 0.5)
        println("$kind|$progress|$direction|${state.alpha}|${state.scale}|${state.dy}")
      }
    }
  }
}
